import hashlib, time, requests

def check_freshness(table, last_load_ts, sla_minutes):
    lag_min = (time.time() - last_load_ts) / 60
    return {
        "table": table,
        "check": "freshness",
        "passed": lag_min <= sla_minutes,
        "lag_minutes": round(lag_min, 1),
        "sla_minutes": sla_minutes,
    }

_recent = {}  # simple in-memory dedup window

def classify_severity(result):
    # Business-critical tables page; others ticket.
    critical = {"gold.daily_revenue", "gold.regulatory_report"}
    if result["table"] in critical:
        return "SEV2"
    return "SEV3"

def dedup_key(result):
    return hashlib.md5(f"{result['table']}:{result['check']}".encode()).hexdigest()

def route_alert(result, dedup_window_s=1800):
    if result["passed"]:
        return
    key = dedup_key(result)
    now = time.time()
    if now - _recent.get(key, 0) < dedup_window_s:
        return  # suppress duplicate within window
    _recent[key] = now
    sev = classify_severity(result)
    msg = (f"[{sev}] {result['table']} {result['check']} FAILED: "
           f"lag={result['lag_minutes']}m > sla={result['sla_minutes']}m")
    if sev in ("SEV1", "SEV2"):
        requests.post("https://events.pagerduty.com/v2/enqueue", json={
            "routing_key": "<PD_ROUTING_KEY>",
            "event_action": "trigger",
            "dedup_key": key,
            "payload": {"summary": msg, "severity": "critical", "source": result["table"]},
        })
    else:
        requests.post("https://hooks.slack.com/services/XXX", json={"text": msg})

res = check_freshness("gold.daily_revenue", last_load_ts=time.time()-3*3600, sla_minutes=60)
route_alert(res)
